def calculate_L_N(N):
    # L_1 = 1/2
    # L_2 = -2/3
    # L_3 = 3/4
    if N == 1:
        return 1/2
    elif N == 2:
        return -2/3
    elif N == 3:
        return 3/4
    else:
        # For demonstration, let's check N=4 if needed, but N=1, 2, 3 are sufficient
        return None

print(f"L_1 = {calculate_L_N(1)}")
